        fx().emit('dust', CAB.x + x, CAB.y + CAB.h - 8, { col: '#7a5230', n: 1.4, power: 1.2 });
        fx().text(270, 430, 'BURIED: ' + name + '. Drop the claw on the mound', '#c8a070');
        fx().shake(3);
        snd('dig');
        break;
