        // a dropping claw with a hanging item between its prongs stops and closes on it (mid-air grab)
        if (K && K.st === 'drop' && geo) { const dy = b.y - K.y; if (dy > 8 && dy < geo.reach * 0.95 && Math.abs(b.x - K.x) < geo.span * 0.35) K.touch = true; }
        b.sl = false; b.slT = 0;
