    if (B.glueArm && idle && !FS.spawnQ.length && S.t - B.glueArmT > 0.5) { B.glueArm = false; gluePairs(B); }
    if (B.snapN) { B.snapN = 0; snd('gooSplat', { pitch: 1.6 }); }
