      if (P.t < D1 && FS.frameN % 3 === 0) fx().emit('dust', CAB.x + P.x - 6, CAB.y + CAB.h - 10, { col: '#8e8a86', n: 0.5 });
      if (P.t < DH + 0.2) FS.beatT = Math.max(FS.beatT, 0.05);
      if (P.t >= DH + D2) B.plow = null;
