      if (C.g === 'slots' && C.win && C.win.tier >= 1 && !S.headless && Math.floor(C.t * 12) !== Math.floor((C.t - dt) * 12)) fx().emit('coins', 250 + Math.sin(C.t * 9) * 60, 700, { n: 0.25 * C.win.tier, power: 0.6, dir: -Math.PI / 2 });
      if (C.winT <= 0) arcWinDone();
