        ARC_BALL.x = P.sim.path[i * 2] + (P.sim.path[j * 2] - P.sim.path[i * 2]) * f;
        ARC_BALL.y = P.sim.path[i * 2 + 1] + (P.sim.path[j * 2 + 1] - P.sim.path[i * 2 + 1]) * f;
