    if (mapLayout()) { const p = hexToStage(M.pos.q, M.pos.r); fx().emit('poof', p.x, p.y); fx().ring(p.x, p.y, '#ff5a4a', { r0: 10, r1: 90, w: 6, life: 0.4 }); }
