    PETM.t = t; PETM.lv = p.lv; PETM.pose = walking ? 'run' : 'sit';
    PETM.mood = walking ? '' : (S.petMapIdle || 0) > 5 ? 'sleep' : (S.petTagFl > 0 ? 'cheer' : '');
    PETM.blink = Math.sin(t * 1.3 + 1) > 0.97 ? 1 : 0;
