      SEC_EPILOGUE.forEach((ln, i) => { const d = h('p', null, ln); try { d.style.animationDelay = (0.8 + i * 1.3).toFixed(2) + 's'; } catch (e) { /* stub */ } ep.appendChild(d); });
      b.appendChild(ep);
      const roll = h('div', 'secRoll');
