    popover(`<b>${e.def.name}</b> ${e.hp}/${e.maxHp}${e.block ? ' +' + e.block + ' block' : ''}<br>${txt}${sts.length ? '<br>' + sts.join(', ') : ''}${afx.length ? '<br>' + afx.join('<br>') : ''}${e.def.desc ? '<br><i>' + e.def.desc + '</i>' : ''}`, p.x, p.y + 26);
    snd('click');
    FS.dirty = true;
