    try { vw = window.innerWidth || W; vh = window.innerHeight || H; } catch (e) { /* headless */ }
    const wrap = $('wrap');
    let iw = vw, ih = vh;
    try { if (wrap && wrap.clientWidth) { iw = wrap.clientWidth; ih = wrap.clientHeight; } } catch (e) { /* ignore */ }
    const k = Math.min(iw / W, ih / H) || 1;
