    const A = X.AUDIO;
    if (A) { try { if (A.setVolume) A.setVolume(ACC_VOL.sfx * s.volSfx, ACC_VOL.music * s.volMusic); if (A.setMaster) A.setMaster(s.volMaster); } catch (e) { /* optional */ } }
