      const b = btn(label + (on ? ' on' : ' off'), () => { fn(!on); accBuild(); }, 'sm toggle accTog ' + (on ? 'on' : ''));
      b.textContent = on ? 'On' : 'Off';   // the row says what it is; GAME.choose keeps the full label
