        ctx.save(); ctx.globalAlpha = a; ctx.fillStyle = 'rgba(8,4,16,0.66)'; ctx.fillRect(0, 0, W, H); ctx.restore();
        ctx.save(); ctx.translate((W - 440) / 2, 200); R.board(ctx, Bd.rows, 440, 560, { t, a, foot: 'TAP TO LEAVE IT GLOWING' }); ctx.restore();
