    const line = w.newMedal ? `${MEDAL_NAME(w.newMedal).toUpperCase()} MEDAL!` : w.medal ? `${MEDAL_NAME(w.medal)} medal · best ${fmtNum(w.best)}` : `best ${fmtNum(w.best)}`;
