    const live = !!(G0 && !G0.done && (S.screen === 'map' || S.screen === 'fight' || S.screen === 'reward' || S.screen === 'shop' || S.screen === 'event' || S.screen === 'rest' || S.screen === 'forge' || S.screen === 'treasure' || S.screen === 'arcade' || S.screen === 'capsule' || S.screen === 'counter'));
