    fx().text(CAB.x + CAB.w / 2 - 30, CAB.y + 60, 'EARTHQUAKE!', '#ff8a2e', { size: 22, life: 1 });
    fx().emit('dust', CAB.x + CAB.w * 0.3, CAB.y + CAB.h - 6, { n: 1, power: 1 });
